mapper.select:
SELECT t.id, t.ledger_id, l.ledger_name, t.category_id, c.category_name, t.pay_channel, t.type, t.amount, t.transaction_time, t.remark, t.tags, t.attach_url, t.created_at, t.updated_at FROM `transaction` t INNER JOIN ledger l ON l.id = t.ledger_id AND l.is_deleted = 0 LEFT JOIN category c ON c.id = t.category_id AND c.is_deleted = 0 WHERE t.is_deleted = 0 AND t.ledger_id = #{ledgerId}
AND t.type = #{type}
AND t.category_id = #{categoryId}
AND t.pay_channel = #{payChannel}
AND t.transaction_time >= #{startTime}
AND t.transaction_time <= #{endTime}
AND t.id >= #{lastLedgerId}
ORDER BY t.transaction_time DESC, t.id DESC
limit #{size}
